    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    margin-top: 8px;
    text-transform: uppercase;
    letter-spacing: 1px;
    box-shadow: 0 4px 15px rgba(74, 158, 255, 0.3);
}

.submit-button:hover:not(:disabled) {
    background: linear-gradient(135deg, #5badff 0%, #2a6ba6 100%);
