+class ContactForm {
+    constructor() {
+        this.form = document.getElementById('contactForm');
+        this.fields = {
+            fullName: {
+                element: document.getElementById('fullName'),
+                errorElement: document.getElementById('fullNameError'),
+                validators: [this.validateRequired]
+            },
+            email: {
+                element: document.getElementById('email'),
+                errorElement: document.getElementById('emailError'),
+                validators: [this.validateRequired, this.validateEmail]
+            },
+            phone: {
+                element: document.getElementById('phone'),
+                errorElement: document.getElementById('phoneError'),
+                validators: [this.validatePhoneFormat]
+            }
+        };
+        this.successMessage = document.getElementById('successMessage');
+        this.init();
+    }
+
+    init() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        
+        Object.values(this.fields).forEach(field => {
+            field.element.addEventListener('blur', () => this.validateField(field));
+            field.element.addEventListener('input', () => this.clearFieldError(field));
+        });
+    }
+
+    validateRequired = (value, fieldName) => {
+        if (!value.trim()) {
+            return `${fieldName} is required`;
+        }
+        return null;
+    }
+
+    validateEmail = (value) => {
+        if (!value.trim()) return null;
+        
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        if (!emailRegex.test(value)) {
+            return 'Please enter a valid email address';
+        }
+        return null;
+    }
+
+    validatePhoneFormat = (value) => {
+        if (!value.trim()) return null;
+        
+        const phoneRegex = /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/;
+        if (!phoneRegex.test(value)) {
+            return 'Please enter a valid phone number';
+        }
+        return null;
+    }
+
+    validateField(field) {
+        for (const validator of field.validators) {
+            const fieldName = this.getFieldName(field);
+            const error = validator(field.element.value, fieldName);
+            
+            if (error) {
+                this.showFieldError(field, error);
+                return false;
+            }
+        }
+        
+        this.clearFieldError(field);
+        return true;
+    }
+
+    getFieldName(field) {
+        const label = field.element.parentElement.querySelector('label');
+        return label ? label.textContent.split('(')[0].trim() : 'Field';
+    }
+
+    showFieldError(field, message) {
+        field.element.classList.add('error');
+        field.errorElement.textContent = message;
+        field.errorElement.classList.add('show');
+    }
+
+    clearFieldError(field) {
+        field.element.classList.remove('error');
+        field.errorElement.textContent = '';
+        field.errorElement.classList.remove('show');
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+        
+        let isFormValid = true;
+        Object.values(this.fields).forEach(field => {
+            if (!this.validateField(field)) {
+                isFormValid = false;
+            }
+        });
+
+        if (isFormValid) {
+            this.submitForm();
+        }
+    }
+
+    submitForm() {
+        const fullName = this.fields.fullName.element.value;
+        const email = this.fields.email.element.value;
+        const phone = this.fields.phone.element.value;
+
+        console.log('Form submitted with:', { fullName, email, phone });
+        
+        this.form.style.display = 'none';
+        this.successMessage.classList.remove('hidden');
+        
+        setTimeout(() => {
+            this.resetForm();
+        }, 3000);
+    }
+
+    resetForm() {
+        this.form.reset();
+        this.form.style.display = 'flex';
+        this.successMessage.classList.add('hidden');
+        
+        Object.values(this.fields).forEach(field => {
+            this.clearFieldError(field);
+        });
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm();
+});
+
